import argparse
import json
import math
from pathlib import Path


def require(condition, message):
    if not condition:
        raise ValueError(message)


def close(actual, expected, message):
    require(
        math.isclose(actual, expected, rel_tol=1e-9, abs_tol=1e-9),
        f"{message}: got {actual}, expected {expected}",
    )


def check_progress(workload, result):
    inputs = {request["id"]: request for request in workload["requests"]}

    progress = {request_id: {"prefilled": 0, "generated": 0} for request_id in inputs}

    # Expected output events generated by the latest batch.
    pending_outputs = {}
    seen_outputs = set()

    for event in result["events"]:
        kind = event["type"]

        if kind == "batch":
            require(
                seen_outputs == set(pending_outputs),
                "missing output-token event after previous batch",
            )
            pending_outputs = {}
            seen_outputs = set()

            expected_context = 0

            for item in event["items"]:
                request_id = item["request"]
                require(request_id in inputs, "unknown request in batch")

                request = inputs[request_id]
                current = progress[request_id]

                require(
                    event["start_us"] >= request["arrival_us"],
                    "request executed before arrival",
                )

                expected_context += current["prefilled"] + current["generated"]

                if item["phase"] == "prefill":
                    remaining = request["prompt_tokens"] - current["prefilled"]
                    require(
                        0 < item["tokens"] <= remaining,
                        "prefill exceeds remaining prompt",
                    )

                    prefill_delta = item["tokens"]
                    final_prefill = prefill_delta == remaining

                    output_delta = int(
                        final_prefill and request["actual_output_tokens"] > 0
                    )

                else:
                    require(item["phase"] == "decode", "unknown phase")
                    require(
                        current["prefilled"] == request["prompt_tokens"],
                        "decode before prefill completion",
                    )
                    require(
                        0 < current["generated"] < request["actual_output_tokens"],
                        "decode after completion or before first token",
                    )

                    prefill_delta = 0
                    output_delta = 1

                require(
                    item["prefill_delta"] == prefill_delta,
                    "incorrect prefill delta",
                )
                require(
                    item["output_delta"] == output_delta,
                    "incorrect output delta",
                )

                current["prefilled"] += prefill_delta
                current["generated"] += output_delta

                if output_delta:
                    pending_outputs[request_id] = (
                        current["generated"],
                        event["end_us"],
                    )

            require(
                event["context_tokens"] == expected_context,
                "batch context does not match replayed request progress",
            )

        elif kind == "output_token":
            request_id = event["request"]

            require(
                request_id in pending_outputs,
                "unexpected output-token event",
            )
            require(
                request_id not in seen_outputs,
                "duplicate output-token event",
            )

            token_index, timestamp = pending_outputs[request_id]

            require(
                event["token_index"] == token_index,
                "incorrect output-token index",
            )
            require(
                event["time_us"] == timestamp,
                "incorrect output-token timestamp",
            )

            seen_outputs.add(request_id)

    require(
        seen_outputs == set(pending_outputs),
        "missing final output-token event",
    )

    reported_ids = set()

    for request in result["requests"]:
        request_id = request["id"]

        require(request_id in inputs, "unknown result request")
        require(request_id not in reported_ids, "duplicate result request")
        reported_ids.add(request_id)

        current = progress[request_id]

        require(
            request["prefilled"] == current["prefilled"],
            "final prefill count mismatch",
        )
        require(
            request["generated"] == current["generated"],
            "final output count mismatch",
        )
        if request["state"] == "completed":
            original = inputs[request_id]
            require(
                current["prefilled"] == original["prompt_tokens"],
                "completed request has unfinished prefill",
            )
            require(
                current["generated"] == original["actual_output_tokens"],
                "completed request has incorrect output length",
            )

    require(reported_ids == set(inputs), "missing result requests")


def check_resources(workload, result):
    inputs = {request["id"]: request for request in workload["requests"]}
    capacity = workload["resources"]["kv_capacity_tokens"]

    reservations = {}
    completed = set()
    cancelled = set()

    used = 0
    peak = 0

    for event in result["events"]:
        kind = event["type"]

        if kind == "kv_reserve":
            request_id = event["request"]
            require(request_id in inputs, "unknown reservation request")
            require(request_id not in reservations, "duplicate KV reservation")
            require(
                request_id not in completed and request_id not in cancelled,
                "terminal request reserved KV",
            )

            request = inputs[request_id]
            require(
                event["time_us"] >= request["arrival_us"],
                "KV reserved before arrival",
            )
            require(
                all(dep in completed for dep in request["dependencies"]),
                "KV reserved before dependencies completed",
            )

            expected = request["prompt_tokens"] + request["max_output_tokens"]
            require(event["tokens"] == expected, "incorrect KV reservation")

            reservations[request_id] = expected
            used += expected
            peak = max(peak, used)

            require(used <= capacity, "KV capacity exceeded")
            require(event["used_tokens"] == used, "KV usage mismatch")

        elif kind == "batch":
            for item in event["items"]:
                request_id = item["request"]

                require(
                    request_id in reservations,
                    "request executed without KV reservation",
                )
                require(
                    request_id not in completed and request_id not in cancelled,
                    "terminal request executed",
                )
                require(
                    all(dep in completed for dep in inputs[request_id]["dependencies"]),
                    "request executed before dependencies completed",
                )

        elif kind == "state":
            request_id = event["request"]
            require(request_id in inputs, "unknown state-change request")

            if event["to"] == "completed":
                require(
                    request_id not in completed and request_id not in cancelled,
                    "duplicate terminal transition",
                )
                require(
                    request_id in reservations,
                    "completion without KV reservation",
                )
                completed.add(request_id)

            elif event["to"] == "cancelled":
                require(
                    request_id not in completed and request_id not in cancelled,
                    "duplicate terminal transition",
                )
                cancelled.add(request_id)

        elif kind == "kv_release":
            request_id = event["request"]

            require(
                request_id in reservations,
                "KV released without reservation or released twice",
            )
            require(
                request_id in completed or request_id in cancelled,
                "KV released before terminal state",
            )

            expected = reservations.pop(request_id)
            require(event["tokens"] == expected, "incorrect KV release")

            used -= expected
            require(event["used_tokens"] == used, "KV release usage mismatch")

    require(not reservations, "KV reservations remain after simulation")
    require(used == 0, "final KV usage is not zero")

    summary = result["summary"]
    require(summary["peak_kv_tokens"] == peak, "peak KV mismatch")
    require(summary["final_kv_tokens"] == used, "final KV mismatch")
    require(summary["completed"] == len(completed), "completed count mismatch")
    require(summary["cancelled"] == len(cancelled), "cancelled count mismatch")

    require(
        completed | cancelled == set(inputs),
        "not all requests reached a terminal state",
    )

    for request in result["requests"]:
        request_id = request["id"]

        if request["state"] == "completed":
            require(request_id in completed, "completion state mismatch")
        elif request["state"] == "cancelled":
            require(request_id in cancelled, "cancellation state mismatch")
        else:
            require(False, "nonterminal result request")


def check_metrics(workload, result):
    inputs = {r["id"]: r for r in workload["requests"]}
    requests = result["requests"]

    completed = [r for r in requests if r["state"] == "completed"]
    cancelled = [r for r in requests if r["state"] == "cancelled"]

    first_arrival = min(
        (r["arrival_us"] for r in inputs.values()),
        default=0,
    )

    last_terminal = max(
        (
            r["completed_us"] if r["state"] == "completed" else r["cancelled_us"]
            for r in requests
        ),
        default=first_arrival,
    )

    duration = last_terminal - first_arrival
    seconds = duration / 1_000_000

    latencies = [r["completed_us"] - inputs[r["id"]]["arrival_us"] for r in completed]

    ttfts = [
        r["first_token_us"] - inputs[r["id"]]["arrival_us"]
        for r in completed
        if r["first_token_us"] is not None
    ]

    waits = [r["admitted_us"] - inputs[r["id"]]["arrival_us"] for r in completed]

    completed_ids = {r["id"] for r in completed}
    previous = {}
    gaps = []

    for event in result["events"]:
        if event["type"] != "output_token":
            continue

        request_id = event["request"]
        if request_id not in completed_ids:
            continue

        time = event["time_us"]

        if request_id in previous:
            gaps.append(time - previous[request_id])

        previous[request_id] = time

    def mean(values):
        return sum(values) / len(values) if values else None

    def p95(values):
        if not values:
            return None
        ordered = sorted(values)
        return ordered[math.ceil(0.95 * len(ordered)) - 1]

    def divide(numerator, denominator):
        return numerator / denominator if denominator > 0 else None

    summary = result["summary"]
    energy = summary["total_j"]
    tokens = summary["generated_tokens"]

    expected = {
        "duration_basis": "first_arrival_to_last_terminal",
        "energy_basis": "engine_zero_origin_horizon",
        "duration_us": duration,
        "completed_requests": len(completed),
        "cancelled_requests": len(cancelled),
        "completed_latency_samples": len(latencies),
        "mean_completed_latency_us": mean(latencies),
        "p95_completed_latency_us": p95(latencies),
        "completed_ttft_samples": len(ttfts),
        "mean_completed_ttft_us": mean(ttfts),
        "p95_completed_ttft_us": p95(ttfts),
        "mean_completed_admission_wait_us": mean(waits),
        "completed_token_gap_samples": len(gaps),
        "mean_completed_token_gap_us": mean(gaps),
        "p95_completed_token_gap_us": p95(gaps),
        "completed_requests_per_second": divide(len(completed), seconds),
        "generated_tokens_per_second": divide(tokens, seconds),
        "dynamic_j": summary["dynamic_j"],
        "background_j": summary["background_j"],
        "total_j": energy,
        "joules_per_completed_request": (
            divide(energy, len(completed)) if not cancelled else None
        ),
        "joules_per_generated_token": divide(energy, tokens),
    }

    metrics = result["metrics"]

    for name, value in expected.items():
        require(name in metrics, f"missing metric: {name}")
        actual = metrics[name]

        if value is None:
            require(actual is None, f"{name} must be null")
        elif isinstance(value, str):
            require(actual == value, f"incorrect metric: {name}")
        else:
            require(
                isinstance(actual, (int, float)) and not isinstance(actual, bool),
                f"{name} must be numeric",
            )
            close(actual, value, f"incorrect metric: {name}")


def check(workload, result):
    require(result["status"] == "success", "simulation failed")
    check_progress(workload, result)
    check_resources(workload, result)
    require(
        result["model_status"] == "SYNTHETIC_PROFILE_NOT_CALIBRATED",
        "this checker currently supports execution_profile only",
    )

    # Read execution parameters, not prediction parameters.
    defaults = {
        "overhead_us": 100,
        "prefill_us": 400,
        "decode_us": 1000,
        "sequence_us": 10,
        "context_us": 1,
        "launch_j": 0.01,
        "prefill_j": 0.08,
        "decode_j": 0.1,
        "quadratic_j": 0.001,
        "context_j": 0.0001,
    }
    profile = {
        **defaults,
        **workload["execution_profile"]["execution"],
    }

    power = workload.get("background_w", 1.0)
    budget = workload["resources"]["max_batch_tokens"]

    clock = 0
    batches = 0
    dynamic_total = 0.0
    background_total = 0.0
    output_tokens = 0

    for event in result["events"]:
        kind = event["type"]

        if kind == "output_token":
            output_tokens += 1
            continue

        if kind not in ("batch", "idle"):
            continue

        start = event["start_us"]
        end = event["end_us"]

        require(start == clock, "execution/idle intervals have a gap or overlap")
        require(end > start, "interval must have positive duration")
        clock = end

        background = power * (end - start) / 1_000_000
        background_total += background

        if kind == "idle":
            close(event["background_j"], background, "idle energy")
            continue

        require(event["batch_index"] == batches, "incorrect batch index")
        batches += 1

        items = event["items"]
        ids = [item["request"] for item in items]
        require(len(ids) == len(set(ids)), "duplicate request in batch")

        prefill = 0
        decode = 0

        for item in items:
            require(item["tokens"] > 0, "nonpositive token count")

            if item["phase"] == "prefill":
                prefill += item["tokens"]
            else:
                require(item["phase"] == "decode", "unknown phase")
                require(item["tokens"] == 1, "decode must process one token")
                decode += 1

        require(0 < prefill + decode <= budget, "batch token budget violated")
        require(event["prefill_tokens"] == prefill, "prefill count mismatch")
        require(event["decode_tokens"] == decode, "decode count mismatch")
        require(event["sequences"] == len(items), "sequence count mismatch")

        # Context is taken from the log in this first checker version.
        context = event["context_tokens"]
        require(context >= 0, "negative context length")
        tokens = prefill + decode

        duration = math.ceil(
            profile["overhead_us"]
            + profile["prefill_us"] * prefill
            + profile["decode_us"] * decode
            + profile["sequence_us"] * len(items)
            + profile["context_us"] * context
        )

        energy = (
            profile["launch_j"]
            + profile["prefill_j"] * prefill
            + profile["decode_j"] * decode
            + profile["quadratic_j"] * tokens * tokens
            + profile["context_j"] * context
        )

        require(end - start == duration, "batch duration formula mismatch")
        require(
            event["actual"]["duration_us"] == duration,
            "logged duration mismatch",
        )
        close(event["actual"]["dynamic_j"], energy, "batch dynamic energy")
        close(event["actual"]["background_j"], background, "batch background")

        dynamic_total += energy

    summary = result["summary"]

    require(summary["batches"] == batches, "summary batch count mismatch")
    require(summary["makespan_us"] == clock, "summary time mismatch")
    require(
        summary["generated_tokens"] == output_tokens,
        "summary output token count mismatch",
    )

    close(summary["dynamic_j"], dynamic_total, "total dynamic energy")
    close(summary["background_j"], background_total, "total background energy")
    close(
        summary["total_j"],
        dynamic_total + background_total,
        "total energy",
    )
    check_metrics(workload, result)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("input", type=Path)
    parser.add_argument("result", type=Path)
    args = parser.parse_args()

    with args.input.open(encoding="utf-8") as file:
        workload = json.load(file)

    with args.result.open(encoding="utf-8") as file:
        result = json.load(file)

    check(workload, result)
    print("PASS: batch accounting, time, and energy")


if __name__ == "__main__":
    main()
